+        ByteBuf byteBuf = userspaceBufferHolder[bid];
+        int mask = entries - 1;
+        long tailFieldAddress = ioUringBufRingAddr + Native.IO_URING_BUFFER_RING_TAIL;
+        short oldTail = PlatformDependent.getShort(tailFieldAddress);
